/**
 * Tool definitions for the Google Cloud console server (MCP name "gcloud").
 *
 * Covers: projects (search, get, create, delete), enabling and disabling APIs
 * (Service Usage), API keys (list, get, create, delete, reveal key string),
 * IAM policy reads, long-running operation polling, and read-only BigQuery
 * (SELECT queries with a dry run first, datasets, tables, table preview, job poll).
 *
 * Auth: OAuth user token from `gsm login cloud`, or Application Default
 * Credentials when no token has been stored. The server entry is generated by
 * scripts/bundle.mjs, which starts it. buildTools makes no network call.
 */
import { serviceusage } from '@googleapis/serviceusage';
import { cloudresourcemanager } from '@googleapis/cloudresourcemanager';
import { apikeys } from '@googleapis/apikeys';
import type { JWT, OAuth2Client } from 'google-auth-library';
import { z } from 'zod';
import type { RuntimeConfig } from '../core/config.js';
import { getAuthClient, googleScopes } from '../core/auth.js';
import { defineTool, type ToolDef } from '../core/tools.js';

type Auth = OAuth2Client | JWT;

// The cloud login is the account's OAuth client, else the Application Default Credentials login (see core/auth.ts).
async function authFor(cfg: RuntimeConfig): Promise<Auth> {
  return getAuthClient('cloud', cfg);
}

/** API keys are scoped by project NUMBER, so IDs are resolved once and cached. */
const projectNumbers = new Map<string, string>();
async function projectNumber(cfg: RuntimeConfig, projectId: string): Promise<string> {
  if (/^\d+$/.test(projectId)) return projectId;
  const cached = projectNumbers.get(projectId);
  if (cached) return cached;
  const rm = cloudresourcemanager({ version: 'v3', auth: await authFor(cfg) });
  const res = await rm.projects.get({ name: `projects/${projectId}` });
  const num = (res.data.name ?? '').replace(/^projects\//, '');
  if (!num) throw new Error(`Could not resolve project number for ${projectId}`);
  projectNumbers.set(projectId, num);
  return num;
}

const projectId = z.string().min(6).max(30).describe('Project ID, for example my-project-123 (not the project number).');

// ---------- BigQuery (read only) ----------
// @googleapis/bigquery is not a dependency, so these calls use the BigQuery REST API
// through the same auth client as the other cloud tools. Nothing here writes data.

const BQ_BASE = 'https://bigquery.googleapis.com/bigquery/v2';
const BQ_READ_SCOPES = googleScopes('bigquery.readonly', 'cloud-platform.read-only', 'bigquery');
const BQ_DEFAULT_MAX_BYTES = 1_000_000_000;
const BQ_MAX_BYTES = 10_000_000_000;

interface BqField {
  name: string;
  type?: string;
  mode?: string;
  description?: string;
  fields?: BqField[];
}
interface BqCell {
  v?: unknown;
}
interface BqRow {
  f?: BqCell[];
}
/** The part of a query or table-data response that holds the schema and the rows. */
interface BqRowSet {
  schema?: { fields?: BqField[] };
  rows?: BqRow[];
}
interface BqQueryResponse extends BqRowSet {
  jobComplete?: boolean;
  jobReference?: { jobId?: string; location?: string };
  totalRows?: string;
  totalBytesProcessed?: string;
  cacheHit?: boolean;
}
interface BqJob {
  statistics?: { totalBytesProcessed?: string; query?: { statementType?: string } };
}
interface BqTable {
  type?: string;
  description?: string;
  location?: string;
  numRows?: string;
  numBytes?: string;
  schema?: { fields?: BqField[] };
}

/**
 * Only a plain SELECT may run through bq_query_read. Scripts, DDL, DML, EXPORT, CALL and
 * anything else are refused after the dry run and before the real query starts.
 */
export function assertReadOnlyStatement(statementType: string | undefined): void {
  if (statementType === 'SELECT') return;
  throw new Error(
    `Only read-only SELECT statements are allowed by bq_query_read. This statement is ${statementType ?? 'unknown'}. Changes to data or schema need a write tool and approval.`,
  );
}

function bqValue(field: BqField, v: unknown): unknown {
  if (v === null || v === undefined) return null;
  if (field.fields?.length && typeof v === 'object') {
    const cells = (v as BqRow).f ?? [];
    return Object.fromEntries(field.fields.map((sub, i) => [sub.name, bqCell(sub, cells[i])]));
  }
  return v;
}

function bqCell(field: BqField, cell: BqCell | undefined): unknown {
  const v = cell?.v;
  if (v === null || v === undefined) return null;
  if (field.mode === 'REPEATED' && Array.isArray(v)) return (v as BqCell[]).map((item) => bqValue(field, item?.v));
  return bqValue(field, v);
}

/**
 * Converts BigQuery's typed cell format ({f: [{v}]} rows plus a schema) into objects keyed by
 * column name. Values stay as the API sends them: int64, float and BOOLEAN come back as strings.
 * Only NULL becomes null; RECORD becomes an object and REPEATED becomes an array.
 */
export function rowsFromQueryResponse(response: BqRowSet): { columns: string[]; rows: Record<string, unknown>[] } {
  const fields = response.schema?.fields ?? [];
  const rows = (response.rows ?? []).map((row) => Object.fromEntries(fields.map((field, i) => [field.name, bqCell(field, row.f?.[i])])));
  return { columns: fields.map((field) => field.name), rows };
}

/** Calls the BigQuery REST API. A Google error body is rethrown with HTTP status, reason and message, as describeError reads them. */
async function bqCall<T>(
  cfg: RuntimeConfig,
  method: 'GET' | 'POST',
  path: string,
  opts: { query?: Record<string, string | number | undefined>; body?: unknown } = {},
): Promise<T> {
  const url = new URL(`${BQ_BASE}/${path}`);
  for (const [key, value] of Object.entries(opts.query ?? {})) {
    if (value !== undefined) url.searchParams.set(key, String(value));
  }
  try {
    // The auth client retries each request (core/auth.ts), so this call is covered.
    const res = await (await authFor(cfg)).request<T>({ url: url.toString(), method, data: opts.body });
    return res.data;
  } catch (err) {
    const e = err as { response?: { status?: number; data?: { error?: { message?: string; code?: number; errors?: Array<{ reason?: string }> } } } };
    const apiError = e?.response?.data?.error;
    if (!apiError?.message) throw err;
    throw Object.assign(new Error(apiError.message), { code: apiError.code ?? e.response?.status, errors: apiError.errors, response: e.response });
  }
}

const bqTablePath = (project: string, dataset: string, table: string) =>
  `projects/${encodeURIComponent(project)}/datasets/${encodeURIComponent(dataset)}/tables/${encodeURIComponent(table)}`;
const bqDataset = z
  .string()
  .min(1)
  .max(1024)
  .regex(/^[A-Za-z0-9_]+$/, 'dataset_id uses letters, digits and underscores only.')
  .describe('Dataset ID, for example analytics_2026.');
const bqTable = z.string().min(1).max(1024).describe('Table ID, for example events.');
const bqLocation = z
  .string()
  .min(1)
  .max(64)
  .optional()
  .describe('Location, for example US or europe-west1. Leave unset to let BigQuery infer it from the datasets; polling a job outside US needs it.');
const bqMaxResults = (max: number, dflt: number) => z.number().int().min(1).max(max).optional().describe(`1 to ${max}. Default ${dflt}.`);

export async function buildTools(cfg: RuntimeConfig): Promise<ToolDef[]> {
  const rm = async () => cloudresourcemanager({ version: 'v3', auth: await authFor(cfg) });
  const su = async () => serviceusage({ version: 'v1', auth: await authFor(cfg) });
  const ak = async () => apikeys({ version: 'v2', auth: await authFor(cfg) });

  return [
    // ---- read ----
    defineTool({
      name: 'cloud_projects_search',
      title: 'Search projects',
      description: 'Search Cloud projects visible to the logged-in account. Query uses Resource Manager search syntax.',
      kind: 'read',
      scopes: googleScopes('cloud-platform', 'cloud-platform.read-only'),
      inputSchema: { query: z.string().optional().describe('For example "displayName:Prod" or "parent.type:folder"') },
      async handler({ query }) {
        const res = await (await rm()).projects.search({ query: query ?? '' });
        return res.data;
      },
    }),
    defineTool({
      name: 'cloud_project_get',
      title: 'Get project',
      description: 'Get one project by project ID.',
      kind: 'read',
      scopes: googleScopes('cloud-platform', 'cloud-platform.read-only'),
      inputSchema: { project_id: projectId },
      async handler({ project_id }) {
        const res = await (await rm()).projects.get({ name: `projects/${project_id}` });
        return res.data;
      },
    }),
    defineTool({
      name: 'cloud_project_iam_policy',
      title: 'Get project IAM policy',
      description: 'Read the IAM policy (who has which role) on a project.',
      kind: 'read',
      scopes: googleScopes('cloud-platform', 'cloud-platform.read-only'),
      inputSchema: { project_id: projectId },
      async handler({ project_id }) {
        const res = await (await rm()).projects.getIamPolicy({ resource: `projects/${project_id}`, requestBody: {} });
        return res.data;
      },
    }),
    defineTool({
      name: 'cloud_services_list',
      title: 'List APIs on a project',
      description: 'List Google APIs on a project. By default only enabled ones.',
      kind: 'read',
      scopes: googleScopes('cloud-platform', 'cloud-platform.read-only'),
      inputSchema: {
        project_id: projectId,
        enabled_only: z.boolean().optional().describe('Default true. Set false to list every available service.'),
      },
      async handler({ project_id, enabled_only }) {
        const res = await (await su()).services.list({
          parent: `projects/${project_id}`,
          filter: enabled_only === false ? undefined : 'state:ENABLED',
          pageSize: 200,
        });
        return res.data.services ?? [];
      },
    }),
    defineTool({
      name: 'cloud_operation_get',
      title: 'Get operation status',
      description: 'Poll a long-running operation (project create, API enable/disable). done=true means it finished.',
      kind: 'read',
      scopes: googleScopes('cloud-platform', 'cloud-platform.read-only', 'service.management'),
      inputSchema: { name: z.string().describe('Operation name, for example operations/abc123') },
      async handler({ name }) {
        try {
          return (await (await rm()).operations.get({ name })).data;
        } catch {
          return (await (await su()).operations.get({ name })).data;
        }
      },
    }),
    defineTool({
      name: 'cloud_apikeys_list',
      title: 'List API keys',
      description: 'List API keys in a project (metadata only, not the secret key string).',
      kind: 'read',
      scopes: googleScopes('apikeys', 'apikeys.readonly', 'cloud-platform', 'cloud-platform.read-only'),
      inputSchema: { project_id: projectId },
      async handler({ project_id }) {
        const num = await projectNumber(cfg, project_id);
        const res = await (await ak()).projects.locations.keys.list({ parent: `projects/${num}/locations/global` });
        return res.data;
      },
    }),
    defineTool({
      name: 'cloud_apikey_get',
      title: 'Get API key',
      description: 'Get API key metadata and restrictions. Key name looks like projects/123/locations/global/keys/UID.',
      kind: 'read',
      scopes: googleScopes('apikeys', 'apikeys.readonly', 'cloud-platform', 'cloud-platform.read-only'),
      inputSchema: { key_name: z.string() },
      async handler({ key_name }) {
        return (await (await ak()).projects.locations.keys.get({ name: key_name })).data;
      },
    }),
    defineTool({
      name: 'cloud_apikey_reveal',
      title: 'Reveal API key string',
      description: 'Return the secret key string of an API key. Treat the output as a credential.',
      // A credential is a write: hidden unless writes are allowed, and the gate asks before it runs.
      kind: 'write',
      scopes: googleScopes('apikeys', 'apikeys.readonly', 'cloud-platform', 'cloud-platform.read-only'),
      inputSchema: { key_name: z.string() },
      async handler({ key_name }) {
        return (await (await ak()).projects.locations.keys.getKeyString({ name: key_name })).data;
      },
    }),

    // ---- read: BigQuery (no DDL or DML here; those come with the approval flow) ----
    defineTool({
      name: 'bq_query_read',
      title: 'Run read-only BigQuery query',
      description:
        'Run one standard SQL SELECT in BigQuery. A dry run first refuses any statement that is not a SELECT, so DDL and DML never run. max_bytes_billed caps the cost. A read-only token also makes Google refuse statements that change data. Returns up to max_rows rows as objects keyed by column. If the job is still running, returns its job_id for bq_job_get.',
      kind: 'read',
      scopes: BQ_READ_SCOPES,
      inputSchema: {
        project_id: projectId.describe('Billing project that runs the query.'),
        query: z.string().min(1).max(100000).describe('One standard SQL SELECT with fully qualified table names, for example `my-project.analytics.events`.'),
        max_bytes_billed: z
          .number()
          .int()
          .min(1)
          .max(BQ_MAX_BYTES)
          .optional()
          .describe(`Cost cap in bytes. Default ${BQ_DEFAULT_MAX_BYTES} (1 GB), max ${BQ_MAX_BYTES} (10 GB).`),
        max_rows: bqMaxResults(1000, 100),
        location: bqLocation,
      },
      async handler({ project_id, query, max_bytes_billed, max_rows, location }) {
        const maxBytes = max_bytes_billed ?? BQ_DEFAULT_MAX_BYTES;
        const maxRows = max_rows ?? 100;
        const jobsPath = `projects/${encodeURIComponent(project_id)}/jobs`;

        // Dry run: bills nothing and reports the statement type and the bytes it would scan.
        const dry = await bqCall<BqJob>(cfg, 'POST', jobsPath, {
          body: {
            jobReference: location ? { projectId: project_id, location } : undefined,
            configuration: { dryRun: true, query: { query, useLegacySql: false } },
          },
        });
        assertReadOnlyStatement(dry.statistics?.query?.statementType);
        const scanned = Number(dry.statistics?.totalBytesProcessed ?? 0);
        if (scanned > maxBytes) {
          throw new Error(
            `This query would scan ${scanned} bytes, more than max_bytes_billed (${maxBytes}). Narrow the query, filter on a partition column, or raise max_bytes_billed up to ${BQ_MAX_BYTES}.`,
          );
        }

        const res = await bqCall<BqQueryResponse>(cfg, 'POST', `projects/${encodeURIComponent(project_id)}/queries`, {
          body: { query, useLegacySql: false, maxResults: maxRows, maximumBytesBilled: String(maxBytes), location },
        });
        const jobId = res.jobReference?.jobId;
        if (res.jobComplete === false) {
          return {
            status: 'running',
            job_id: jobId,
            location: res.jobReference?.location,
            message: 'The query is still running. Call bq_job_get with this job_id and location to fetch the rows.',
          };
        }
        const { columns, rows } = rowsFromQueryResponse(res);
        return {
          status: 'done',
          job_id: jobId,
          total_rows: res.totalRows,
          columns,
          rows,
          bytes_processed: res.totalBytesProcessed,
          cache_hit: res.cacheHit ?? false,
        };
      },
    }),
    defineTool({
      name: 'bq_job_get',
      title: 'Get BigQuery job rows',
      description:
        'Check a query job that bq_query_read started and did not finish in time, and return its rows once it is done. Call again while status is running.',
      kind: 'read',
      scopes: BQ_READ_SCOPES,
      inputSchema: {
        project_id: projectId,
        job_id: z.string().min(1).max(1024).describe('job_id returned by bq_query_read.'),
        location: bqLocation,
        max_rows: bqMaxResults(1000, 100),
      },
      async handler({ project_id, job_id, location, max_rows }) {
        const res = await bqCall<BqQueryResponse>(
          cfg,
          'GET',
          `projects/${encodeURIComponent(project_id)}/queries/${encodeURIComponent(job_id)}`,
          { query: { location, maxResults: max_rows ?? 100 } },
        );
        if (res.jobComplete === false) {
          return { status: 'running', job_id, message: 'Still running. Call bq_job_get again in a little while.' };
        }
        const { columns, rows } = rowsFromQueryResponse(res);
        return { status: 'done', job_id, total_rows: res.totalRows, columns, rows, bytes_processed: res.totalBytesProcessed };
      },
    }),
    defineTool({
      name: 'bq_dataset_list',
      title: 'List BigQuery datasets',
      description: 'List the datasets in a project with their IDs, locations and friendly names.',
      kind: 'read',
      scopes: BQ_READ_SCOPES,
      inputSchema: { project_id: projectId, max_results: bqMaxResults(1000, 100) },
      async handler({ project_id, max_results }) {
        const res = await bqCall<{
          datasets?: Array<{ datasetReference?: { datasetId?: string }; location?: string; friendlyName?: string }>;
          nextPageToken?: string;
        }>(cfg, 'GET', `projects/${encodeURIComponent(project_id)}/datasets`, { query: { maxResults: max_results ?? 100 } });
        return {
          datasets: (res.datasets ?? []).map((d) => ({
            dataset_id: d.datasetReference?.datasetId,
            location: d.location,
            friendly_name: d.friendlyName,
          })),
          has_more: Boolean(res.nextPageToken),
        };
      },
    }),
    defineTool({
      name: 'bq_table_list',
      title: 'List BigQuery tables',
      description: 'List the tables and views in one dataset, with their types (TABLE, VIEW, MATERIALIZED_VIEW, EXTERNAL, SNAPSHOT).',
      kind: 'read',
      scopes: BQ_READ_SCOPES,
      inputSchema: { project_id: projectId, dataset_id: bqDataset, max_results: bqMaxResults(1000, 100) },
      async handler({ project_id, dataset_id, max_results }) {
        const res = await bqCall<{
          tables?: Array<{ tableReference?: { tableId?: string }; type?: string; friendlyName?: string }>;
          nextPageToken?: string;
        }>(cfg, 'GET', `projects/${encodeURIComponent(project_id)}/datasets/${encodeURIComponent(dataset_id)}/tables`, {
          query: { maxResults: max_results ?? 100 },
        });
        return {
          tables: (res.tables ?? []).map((t) => ({ table_id: t.tableReference?.tableId, type: t.type, friendly_name: t.friendlyName })),
          has_more: Boolean(res.nextPageToken),
        };
      },
    }),
    defineTool({
      name: 'bq_table_get',
      title: 'Get BigQuery table schema',
      description: 'Return one table or view: its type, description, row and byte counts, and the schema with nested fields.',
      kind: 'read',
      scopes: BQ_READ_SCOPES,
      inputSchema: { project_id: projectId, dataset_id: bqDataset, table_id: bqTable },
      async handler({ project_id, dataset_id, table_id }) {
        const res = await bqCall<BqTable>(cfg, 'GET', bqTablePath(project_id, dataset_id, table_id));
        return {
          dataset_id,
          table_id,
          type: res.type,
          description: res.description,
          location: res.location,
          num_rows: res.numRows,
          num_bytes: res.numBytes,
          schema: res.schema?.fields ?? [],
        };
      },
    }),
    defineTool({
      name: 'bq_table_preview',
      title: 'Preview BigQuery table rows',
      description: 'Return the first rows of a table with tabledata.list. This reads rows without running a query, so it has no query cost.',
      kind: 'read',
      scopes: BQ_READ_SCOPES,
      inputSchema: {
        project_id: projectId,
        dataset_id: bqDataset,
        table_id: bqTable,
        max_rows: bqMaxResults(500, 50),
      },
      async handler({ project_id, dataset_id, table_id, max_rows }) {
        const path = bqTablePath(project_id, dataset_id, table_id);
        // tabledata.list does not return the schema, so the table is read for its column names.
        const [meta, data] = await Promise.all([
          bqCall<BqTable>(cfg, 'GET', path),
          bqCall<BqRowSet & { totalRows?: string }>(cfg, 'GET', `${path}/data`, { query: { maxResults: max_rows ?? 50 } }),
        ]);
        const { columns, rows } = rowsFromQueryResponse({ schema: meta.schema, rows: data.rows });
        return { dataset_id, table_id, total_rows: data.totalRows, columns, rows };
      },
    }),

    // ---- write (registered only when GSM_ALLOW_WRITES=true) ----
    defineTool({
      name: 'cloud_project_create',
      title: 'Create project',
      description: 'Create a Cloud project. Returns a long-running operation; poll with cloud_operation_get.',
      kind: 'write',
      scopes: googleScopes('cloud-platform'),
      inputSchema: {
        project_id: projectId,
        display_name: z.string().min(4).max(30),
        parent: z.string().optional().describe('For example folders/123 or organizations/456. Omit for no parent.'),
      },
      async handler({ project_id, display_name, parent }) {
        const res = await (await rm()).projects.create({
          requestBody: { projectId: project_id, displayName: display_name, parent },
        });
        return res.data;
      },
    }),
    defineTool({
      name: 'cloud_service_enable',
      title: 'Enable API',
      description: 'Enable a Google API on a project, for example calendar-json.googleapis.com for Calendar.',
      kind: 'write',
      scopes: googleScopes('cloud-platform', 'service.management'),
      inputSchema: { project_id: projectId, service: z.string().describe('For example calendar-json.googleapis.com') },
      async handler({ project_id, service }) {
        const res = await (await su()).services.enable({
          name: `projects/${project_id}/services/${service}`,
          requestBody: {},
        });
        return res.data;
      },
    }),
    defineTool({
      name: 'cloud_apikey_create',
      title: 'Create API key',
      description: 'Create an API key, optionally restricted to specific API services. Returns a long-running operation.',
      kind: 'write',
      scopes: googleScopes('apikeys', 'cloud-platform'),
      inputSchema: {
        project_id: projectId,
        display_name: z.string(),
        api_targets: z.array(z.string()).optional().describe('Services the key may call, for example ["calendar-json.googleapis.com"]'),
      },
      async handler({ project_id, display_name, api_targets }) {
        const num = await projectNumber(cfg, project_id);
        const res = await (await ak()).projects.locations.keys.create({
          parent: `projects/${num}/locations/global`,
          requestBody: {
            displayName: display_name,
            restrictions: api_targets?.length ? { apiTargets: api_targets.map((service) => ({ service })) } : undefined,
          },
        });
        return res.data;
      },
    }),

    // ---- destructive (asks for approval before each call) ----
    defineTool({
      name: 'cloud_project_delete',
      title: 'Delete project',
      description: 'Schedule a project for deletion (recoverable for a limited time). Deletes every resource in it eventually.',
      kind: 'destructive',
      scopes: googleScopes('cloud-platform'),
      inputSchema: { project_id: projectId },
      preview: ({ project_id }) => ({ project: project_id, effect: 'Project is scheduled for deletion along with its resources.' }),
      async handler({ project_id }) {
        const res = await (await rm()).projects.delete({ name: `projects/${project_id}` });
        return res.data;
      },
    }),
    defineTool({
      name: 'cloud_service_disable',
      title: 'Disable API',
      description:
        'Disable a Google API on a project. Can delete resources (for example Cloud Run services) and suspend GKE clusters. Check the effects first.',
      kind: 'destructive',
      scopes: googleScopes('cloud-platform', 'service.management'),
      inputSchema: {
        project_id: projectId,
        service: z.string(),
        disable_dependent_services: z.boolean().optional().describe('Also disable services that depend on this one. Default false.'),
      },
      preview: ({ project_id, service, disable_dependent_services }) => ({
        project: project_id,
        service,
        disableDependentServices: disable_dependent_services ?? false,
        effect: 'Resources of this API may be deleted or suspended. Stored data is kept but still billed.',
      }),
      async handler({ project_id, service, disable_dependent_services }) {
        const res = await (await su()).services.disable({
          name: `projects/${project_id}/services/${service}`,
          requestBody: { disableDependentServices: disable_dependent_services ?? false },
        });
        return res.data;
      },
    }),
    defineTool({
      name: 'cloud_apikey_delete',
      title: 'Delete API key',
      description: 'Delete an API key. It is marked deleted at once and can be restored within 30 days.',
      kind: 'destructive',
      scopes: googleScopes('apikeys', 'cloud-platform'),
      inputSchema: { key_name: z.string() },
      preview: ({ key_name }) => ({ key: key_name, effect: 'Key stops working immediately. Restorable for 30 days.' }),
      async handler({ key_name }) {
        const res = await (await ak()).projects.locations.keys.delete({ name: key_name });
        return res.data;
      },
    }),
  ];
}
